<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;
AccessControl::require('payments.manage');$rows=Database::connection()->query("SELECT py.*,p.patient_number,p.full_name FROM payments py JOIN patients p ON p.id=py.patient_id ORDER BY py.id DESC LIMIT 100")->fetchAll();require dirname(__DIR__).'/_layout_top.php';?>
<div class="d-flex justify-content-between mb-3"><h2>Payments</h2><a class="btn btn-primary" href="/payments/create.php">Record payment</a></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Receipt</th><th>Patient</th><th>Amount</th><th>Method</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['receipt_number'])?></td><td><?=e($r['patient_number'].' - '.$r['full_name'])?></td><td><?=number_format((float)$r['amount'],2)?></td><td><?=e($r['payment_method'])?></td><td><?=e($r['paid_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php require dirname(__DIR__).'/_layout_bottom.php';?>
